INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(45711, 'Deuteronomy 4:4', 'Deuteronomy', 4, 4, 'خو ستاسو څخه چې څوک خپل څښتن خدای ته وفادار وو، هغوی تر نن ورځې پورې ژوندي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_4.mp3', '', 1761754199, 1761754199),
(45712, 'Deuteronomy 4:5', 'Deuteronomy', 4, 5, 'ما د خپل څښتن خدای د وینا سره سم تاسو ته ټول قوانین درزده کړي دي. د هغو اطاعت په هغه خاوره کې کوئ چې تاسو به ورننوځئ او هغه به ونیسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_5.mp3', '', 1761754199, 1761754199),
(45713, 'Deuteronomy 4:6', 'Deuteronomy', 4, 6, 'په وفادارۍ سره د هغو اطاعت وکړئ، نو دا کار به نورو قومونو ته دا خبره په ډاګه کړي چې تاسو څومره پوه خلک یئ. کله چې هغوی د دغو ټولو قوانینو په هکله واوري، داسې به وایي: ‹دا لوی قوم څومره حکمت او پوهه لري!›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_6.mp3', '', 1761754199, 1761754199),
(45714, 'Deuteronomy 4:7', 'Deuteronomy', 4, 7, 'بل هېڅ قوم چې هرڅومره لوی وي داسې خدای نه لري چې هغوی ته د اړتیا په وخت کې دومره نژدې وي لکه څنګه چې مونږ ته خپل څښتن خدای نژدې دی. هرکله چې مونږ د مرستې دپاره سوال وکړو، هغه یې قبلوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_7.mp3', '', 1761754199, 1761754199),
(45715, 'Deuteronomy 4:8', 'Deuteronomy', 4, 8, 'بل هېڅ قوم چې هرڅومره لوی وي داسې عادلانه قوانین نه لري لکه ما چې تاسو ته نن درزده کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_8.mp3', '', 1761754199, 1761754199),
(45716, 'Deuteronomy 4:11', 'Deuteronomy', 4, 11, 'خپلو اولادونو ته ووایئ چې تاسو څرنګه لاړئ او د هغه غره په لمنه کې ودرېدلئ چې هلته ټینګه ورېځ او توره تیاره وه او اور ورڅخه اسمان ته پورته کېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_11.mp3', '', 1761754199, 1761754199),
(45717, 'Deuteronomy 4:12', 'Deuteronomy', 4, 12, 'هغوی ته ووایئ چې څښتن څنګه ستاسو سره د اور له منځ څخه خبرې وکړې، څنګه تاسو د هغه خبرې واورېدلې، خو د هغه څېره مو ونه لیدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_12.mp3', '', 1761754199, 1761754199),
(45718, 'Deuteronomy 4:13', 'Deuteronomy', 4, 13, 'هغه درته وویل د دې دپاره چې په هغه لوظ باندې ودرېږئ چې هغه ستاسو سره کړی دی څه باید وکړئ. تاسو باید د هغو لسو حکمونو اطاعت وکړئ چې هغه د تیږو په دوو لوحو باندې لیکلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_13.mp3', '', 1761754199, 1761754199),
(45719, 'Deuteronomy 4:14', 'Deuteronomy', 4, 14, 'څښتن ماته وویل چې تاسو ته به هغه ټول قوانین درزده کړم چې باید په هغه خاوره کې یې اطاعت وکړئ چې نژدې ده چې حمله ورباندې وکړئ او هغه ونیسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_14.mp3', '', 1761754199, 1761754199),
(45720, 'Deuteronomy 4:19', 'Deuteronomy', 4, 19, 'کله چې تاسو اسمان ته ګورئ او لمر، سپوږمۍ او ستوري وینئ، نو وسوسه کېږئ مه چې هغو ته سجده وکړئ یا یې عبادت وکړئ. ستاسو څښتن خدای دا شیان د نړۍ نورو قومونو ته ورکړي دي چې عبادت یې وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_19.mp3', '', 1761754199, 1761754199),
(45721, 'Deuteronomy 4:20', 'Deuteronomy', 4, 20, 'خو تاسو هغه قوم یئ چې هغه د مصر څخه راوویست، یعنې د اور نه د ډک داش څخه. هغه د دې دپاره راوویستلئ چې ستاسو څخه خپل قوم جوړ کړي لکه څنګه چې نن یئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_20.mp3', '', 1761754199, 1761754199),
(45722, 'Deuteronomy 4:21', 'Deuteronomy', 4, 21, 'څښتن ستاسو په خاطر په ما باندې په قهر شو، قسم یې وخوړ او ویې ویل چې ته نه شې کولای د اردن د سیند څخه هغې حاصلخېزې ځمکې ته واوړې چې زه یې خپل قوم ته ورکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_21.mp3', '', 1761754199, 1761754199),
(45723, 'Deuteronomy 4:22', 'Deuteronomy', 4, 22, 'نو زه موسی به په دې خاوره کې مړ شم او هېڅکله به د سیند څخه تېر نه شم، خو تاسو دې ته نژدې یئ چې ورڅخه تېر شئ او هغه حاصلخېزه ځمکه ونیسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_22.mp3', '', 1761754199, 1761754199),
(45724, 'Deuteronomy 4:23', 'Deuteronomy', 4, 23, 'پام کوئ هغه لوظ به نه هېروئ چې ستاسو څښتن خدای ستاسو سره کړی دی. د هغه د امر اطاعت وکړئ چې تاسو به د خپلو ځانونو دپاره هېڅ ډول بت نه جوړوئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_23.mp3', '', 1761754199, 1761754199),
(45725, 'Deuteronomy 4:24', 'Deuteronomy', 4, 24, 'که چېرې تاسو د نورو خدایانو عبادت وکړئ، نو ستاسو څښتن خدای غیرتي او تباه کوونکی اور دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_24.mp3', '', 1761754199, 1761754199),
(45726, 'Deuteronomy 4:25', 'Deuteronomy', 4, 25, 'کله چې په هغه وطن کې ډېره موده واوسېږئ او اولادونه او لمسیان مو پیدا شي، نو د هېڅ شي په شکل کې به د بت په جوړولو سره ګناه نه کوئ. دا د څښتن په نظر کې بد کار دی او هغه به په دې کار په قهر شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_25.mp3', '', 1761754199, 1761754199),
(45727, 'Deuteronomy 4:26', 'Deuteronomy', 4, 26, 'زه همدا نن ځمکه او اسمان ستاسو په وړاندې شاهدان نیسم، که چېرې زما څخه نافرماني وکړئ، نو زر به د هغې ځمکې د مخ څخه ورک شئ. تاسو به په هغه خاوره کې ډېره موده ژوند ونه کړئ چې د اردن په بله غاړه باندې پرته ده او تاسو یې نیسئ. تاسو به بیخي تباه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_26.mp3', '', 1761754199, 1761754199),
(45728, 'Deuteronomy 4:27', 'Deuteronomy', 4, 27, 'څښتن به تاسو په نورو قومونو کې خپاره کړي او ستاسو څخه به یوازې څو تنه په کې ژوندي پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_27.mp3', '', 1761754199, 1761754199),
(45729, 'Deuteronomy 4:28', 'Deuteronomy', 4, 28, 'تاسو به هلته د داسې خدایانو عبادت کوئ چې د انسانانو په لاسونو جوړ شوي دي، داسې خدایان چې د لرګیو او تیږو څخه جوړ شوي دي چې لیدلی یا اورېدلی نه شي او څه خوړلی یا بوی کولای نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_28.mp3', '', 1761754199, 1761754199),
(45730, 'Deuteronomy 4:29', 'Deuteronomy', 4, 29, 'خو که چېرې هلته د خپل څښتن خدای د لټولو پرېکړه وکړئ او تاسو هغه د زړه له کومي ولټوئ، نو هغه به پیدا کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_29.mp3', '', 1761754199, 1761754199),
(45731, 'Deuteronomy 4:30', 'Deuteronomy', 4, 30, 'کله چې تاسو د ستونزو سره مخامخ شئ او دا ټول شیان درباندې راشي، نو په پای کې به څښتن ته رجوع وکړئ او د هغه اطاعت به وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_30.mp3', '', 1761754199, 1761754199),
(45732, 'Deuteronomy 4:31', 'Deuteronomy', 4, 31, 'هغه زړه سواندی خدای دی. هغه به ستاسو څخه مخ نه اړوي او نه به تاسو تباه کوي او هغه لوظ به هېر نه کړي چې هغه په خپله ستاسو د نیکونو سره کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_31.mp3', '', 1761754199, 1761754199),
(45733, 'Deuteronomy 4:32', 'Deuteronomy', 4, 32, 'تېر شوي وخت ته وګورئ یعنې هغه وخت چې تاسو پیدا شوي نه وئ او له هغه وخت څخه چې خدای د ځمکې په مخ انسانان پیدا کړل. ټوله نړۍ ولټوئ، ایا داسې لوی لوی کارونه مخکې کله شوي دي؟ ایا داسې شیان چا کله اورېدلي دي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_32.mp3', '', 1761754199, 1761754199),
(45734, 'Deuteronomy 4:33', 'Deuteronomy', 4, 33, 'ایا داسې قوم شته چې کوم خدای د هغه سره د اور د منځ څخه خبرې کړې وي او هغه یې ستاسو په شان اورېدلې وي او ژوندی پاتې شوی وي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_33.mp3', '', 1761754199, 1761754199),
(45735, 'Deuteronomy 4:34', 'Deuteronomy', 4, 34, 'ایا کوم خدای داسې جرات کړی دی چې لاړ شي او د بل قوم څخه هغه قوم راواخلي چې د هغوی سره غلامان وو او خپل قوم ورڅخه جوړ کړي، لکه څنګه چې ستاسو څښتن خدای په مصر کې ستاسو دپاره وکړ؟ هغه ستاسو د سترګو په وړاندې د خپل قوي مټ او ټول قدرت څخه کار واخیست. هغه افتونه او جنګ راوست، معجزې یې وښودلې او عجیبه عجیبه کارونه یې وکړل او وېروونکې پېښې یې رامنځته کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_34.mp3', '', 1761754199, 1761754199),
(45736, 'Deuteronomy 4:35', 'Deuteronomy', 4, 35, 'څښتن دا شیان د دې دپاره دروښودل چې تاسو ته دا خبره ثابته کړي چې یوازې هغه خدای دی او بل خدای نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_35.mp3', '', 1761754199, 1761754199),
(45737, 'Deuteronomy 4:36', 'Deuteronomy', 4, 36, 'هغه تاسو پرېښودلئ چې د اسمان څخه د هغه غږ واورئ، ترڅو تاسو په سمه لاره برابر کړي. هغه په ځمکه باندې تاسو ته خپل وېروونکی اور وښود او تاسو د اور د منځ څخه د هغه خبرې واورېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_36.mp3', '', 1761754199, 1761754199),
(45738, 'Deuteronomy 4:37', 'Deuteronomy', 4, 37, 'د دې په خاطر چې هغه ستاسو د نیکونو سره مینه درلودله، نو د هغوی څخه وروسته یې د هغوی اولاده یعنې تاسو غوره کړئ او په خپل لوی قدرت یې په خپله د مصر څخه راوویستلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_37.mp3', '', 1761754199, 1761754199),
(45739, 'Deuteronomy 4:38', 'Deuteronomy', 4, 38, 'اوس تاسو د نورو قومونو سره چې ستاسو څخه قوي دي مخامخ یئ، خو څښتن لا د مخکې نه د خپلې خاورې څخه د هغوی په شړلو پیل کړی دی او هغه تاسو ته درکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_38.mp3', '', 1761754199, 1761754199),
(45740, 'Deuteronomy 4:39', 'Deuteronomy', 4, 39, 'نو همدا نن یاد ساتئ او هېڅکله دا خبره هېره نه کړئ چې څښتن د اسمانونو او ځمکې خدای دی او بل خدای نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_39.mp3', '', 1761754199, 1761754199),
(45741, 'Deuteronomy 4:40', 'Deuteronomy', 4, 40, 'د هغه د هغو ټولو قوانینو اطاعت کوئ چې نن مې تاسو ته درکړل، نو ستاسو او ستاسو د اولادې هر کار به سم وي. تاسو به په هغه وطن کې چې ستاسو څښتن خدای یې تاسو ته د تل دپاره درکوي، اوږد ژوند ولرئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_40.mp3', '', 1761754199, 1761754199),
(45742, 'Deuteronomy 4:41', 'Deuteronomy', 4, 41, 'بیا موسی د اردن د سیند په ختیځ کې درې ښارونه بېل کړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_41.mp3', '', 1761754199, 1761754199),
(45743, 'Deuteronomy 4:42', 'Deuteronomy', 4, 42, 'ترڅو داسې سړی هلته وتښتي او خوندي پاتې شي چې په سهوې سره یې یو داسې کس وژلی وي چې دښمن یې نه وي. هغه کولای شي چې د دغو ښارونو څخه یو ښار ته وتښتي او خپل ژوند وژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_42.mp3', '', 1761754199, 1761754199),
(45744, 'Deuteronomy 4:43', 'Deuteronomy', 4, 43, 'د روبین د قبیلې دپاره د باصر ښار ؤ چې د دښتې په لوړه جلګه باندې پروت ؤ. د جاد د قبیلې دپاره راموت ؤ چې د جلعاد په سیمه کې پروت ؤ او د منسي د قبیلې دپاره د جولان ښار ؤ چې د باشان په سیمه کې پروت ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_43.mp3', '', 1761754199, 1761754199),
(45745, 'Deuteronomy 4:44', 'Deuteronomy', 4, 44, 'موسی د اسراییلو قوم ته د خدای قوانین ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_44.mp3', '', 1761754199, 1761754199),
(45746, 'Deuteronomy 4:47', 'Deuteronomy', 4, 47, 'هغوی د سیحون او د باشان د پاچا یعنې د عوج خاوره ونیوله. عوج د اموریانو بل پاچا ؤ چې د اردن په ختیځ کې اوسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_47.mp3', '', 1761754199, 1761754199),
(45747, 'Deuteronomy 4:48', 'Deuteronomy', 4, 48, 'دا خاوره د عروعیر د ښار څخه چې د ارنون د سیند په غاړه پروت ؤ، په شمال کې د سریون یعنې د حرمون تر غره پورې غزېدلې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_48.mp3', '', 1761754199, 1761754199),
(45748, 'Deuteronomy 4:49', 'Deuteronomy', 4, 49, 'په هغې کې د اردن د سیند ټوله ختیځه سیمه تر مړې بحیرې او د پیسګاه د غره تر لمنې پورې شامله وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_49.mp3', '', 1761754199, 1761754199),
(45749, 'Psalms 97:1', 'Psalms', 97, 1, 'څښتن پاچا دی نو ای ځمکې خوښي وکړه! ټولو ټاپو‌ګانو خوشحالي وکړئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms97_verse_1.mp3', '', 1761754199, 1761754199),
(45750, 'Psalms 97:2', 'Psalms', 97, 2, 'ترې چاپېره دي تورې تیارې او ورېځې ایښودل شوی دی بنیاد د پاچاهۍ یې په عدالت او په انصاف باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms97_verse_2.mp3', '', 1761754199, 1761754199),
(45751, 'Psalms 97:3', 'Psalms', 97, 3, 'اور دی روان یې مخکې سوځوي یې دښمنان په شاوخوا کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms97_verse_3.mp3', '', 1761754199, 1761754199),
(45752, 'Psalms 97:4', 'Psalms', 97, 4, 'برېښنا‌ګانې یې نړۍ رڼا کوي ځمکه چې وویني هغه نو پرې لړزان راشي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms97_verse_4.mp3', '', 1761754199, 1761754199),
(45753, 'Psalms 97:5', 'Psalms', 97, 5, 'ویلې کیږي غرونه لکه د موم په شان د څښتن مخکې د ټول جهان د څښتن مخکې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms97_verse_5.mp3', '', 1761754199, 1761754199),
(45754, 'Psalms 97:6', 'Psalms', 97, 6, 'اسمانونه عدالت اعلانوي د هغه او ټول قومونه یې جلال ویني', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms97_verse_6.mp3', '', 1761754199, 1761754199),
(45755, 'Psalms 97:7', 'Psalms', 97, 7, 'ټول هغه خلک چې عبادت کړي د بې‌فایدې بتانو ویاړ په عبادت چې د بتانو بې‌ارزښتو کړي هغه به وشرمیږي ای نورو ټولو خدایانو وکړئ څښتن ته سجده!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms97_verse_7.mp3', '', 1761754199, 1761754199),
(45756, 'Psalms 97:8', 'Psalms', 97, 8, 'ای څښتنه ستا قضاوتونو باندې په اورېدو یې خوشحالي کوي د صهیون خلک کوي خوښي د یهودا ښارونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms97_verse_8.mp3', '', 1761754199, 1761754199),
(45757, 'Psalms 97:9', 'Psalms', 97, 9, 'ځکه چې ته یې متعال ټولې نړۍ ته ای څښتنه ته یې ډېر لوی له نورو ټولو خدایانو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms97_verse_9.mp3', '', 1761754199, 1761754199),
(45758, 'Psalms 97:10', 'Psalms', 97, 10, 'ای تاسو خلکو چې کوئ مینه د څښتن سره نو کوئ کرکه له بدۍ څخه! هغه خوندي ساتي د خپلو وفادارو ژوندون هم یې له لاسه د بدکارو ژغوري', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms97_verse_10.mp3', '', 1761754199, 1761754199),
(45759, 'Psalms 97:11', 'Psalms', 97, 11, 'ځلیږي نور په عادلانو باندې خوشحالي په برخه کیږي د نېکانو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms97_verse_11.mp3', '', 1761754199, 1761754199),
(45760, 'Psalms 97:12', 'Psalms', 97, 12, 'ای نېکو خلکو، خوشحالي هغو کارو ته وکړئ کوم چې څښتن کړي دي د هغه د سپېڅلي نوم شکر وکړئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms97_verse_12.mp3', '', 1761754199, 1761754199),
(45761, 'Psalms 6:1', 'Psalms', 6, 1, 'مه په قهرېږه ای څښتنه او ما مه رټه ته په خپل غضب سره دې ماته سزا مه راکوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms6_verse_1.mp3', '', 1761754199, 1761754199),
(45762, 'Psalms 6:2', 'Psalms', 6, 2, 'زه یم کمزوری ای څښتنه، په ما رحم وکړه! ماته شفا راکړه څښتنه، چې هډوکي ټول خوږیږي زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms6_verse_2.mp3', '', 1761754199, 1761754199),
(45763, 'Psalms 6:3', 'Psalms', 6, 3, 'څښتنه زه ډېر په کړاو کې یمه دا به ترڅو پورې تر کومې به وي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms6_verse_3.mp3', '', 1761754199, 1761754199),
(45764, 'Psalms 6:4', 'Psalms', 6, 4, 'ای څښتنه زما! راشه ما وژغوره په خپلې مینې دې له مرګه ما راخلاص کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms6_verse_4.mp3', '', 1761754199, 1761754199),
(45765, 'Psalms 6:5', 'Psalms', 6, 5, 'کله چې څوک مړ شي بیا تا نه شي یادولی ګور کې هېڅوک نه شي ستا ثنا بیانولی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms6_verse_5.mp3', '', 1761754199, 1761754199),
(45766, 'Psalms 6:6', 'Psalms', 6, 6, 'په زګېروو شومه زه ستړی هره شپه مې بستر لوند وي په ژړا هم مې لوند بالښت په اوښکو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms6_verse_6.mp3', '', 1761754199, 1761754199),
(45767, 'Psalms 6:7', 'Psalms', 6, 7, 'دید مې ډېر کمزوری شوی له غمو زما سترګې پړسېدلې له ژړا نه په سبب د دښمنانو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms6_verse_7.mp3', '', 1761754199, 1761754199),
(45768, 'Psalms 6:8', 'Psalms', 6, 8, 'ای بدکارو خلکو، لېرې شئ له ما اورېدلې ده څښتن ژړا زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms6_verse_8.mp3', '', 1761754199, 1761754199),
(45769, 'Psalms 6:9', 'Psalms', 6, 9, 'د کومک دپاره واورېده څښتن فریاد زما کړي قبوله به هغه دعا زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms6_verse_9.mp3', '', 1761754199, 1761754199),
(45770, 'Psalms 6:10', 'Psalms', 6, 10, 'زما دښمنان به ټول شرمیږي او وېریږي به ډېر هغوی به تښتي ناڅاپي په رسوایۍ سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms6_verse_10.mp3', '', 1761754199, 1761754199),
(45771, 'Job 38:1', 'Job', 38, 1, 'نو مالِک خُدائ د طوفان نه ايُوب له جواب ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_1.mp3', '', 1761754199, 1761754199),
(45772, 'Job 38:2', 'Job', 38, 2, '”هغه څوک دے چې بغېر د څۀ پوهې نه زما د عقل په حقله تپوسونه کوى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_2.mp3', '', 1761754199, 1761754199),
(45773, 'Job 38:3', 'Job', 38, 3, 'نو اوس ټينګ شه، او زما د سوال جواب راکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_3.mp3', '', 1761754199, 1761754199),
(45774, 'Job 38:4', 'Job', 38, 4, 'کله چې ما د زمکې بنياد کېښودو نو تۀ چرته وې؟ کۀ تا ته دومره پته وى نو ما ته ووايه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_4.mp3', '', 1761754199, 1761754199),
(45775, 'Job 38:5', 'Job', 38, 5, 'چې دا به څومره غټ وى د دې پته چا لګولى ده؟ او په دې چا د ناپ کرښه راښکلې ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_5.mp3', '', 1761754199, 1761754199),
(45776, 'Job 38:6', 'Job', 38, 6, 'د دې بنيادونه په څۀ باندې ودرېدل، او د دې د ګوټ کاڼے چا کېښودو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_6.mp3', '', 1761754199, 1761754199),
(45777, 'Job 38:7', 'Job', 38, 7, 'چې کله د سحر ستورو په يو ځائ سندرې وئيلې او ټولو فرښتو د خوشحالۍ نه چغې وهلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_7.mp3', '', 1761754199, 1761754199),
(45778, 'Job 38:8', 'Job', 38, 8, 'کله چې سمندر زمکې ته راخلاص شو، نو دا چا قابو کړو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_8.mp3', '', 1761754199, 1761754199),
(45779, 'Job 38:9', 'Job', 38, 9, 'کله چې ما وريځ د دې لِباس جوړ کړو، او دا ما په تکه توره تيارۀ کښې راونغښتلو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_9.mp3', '', 1761754199, 1761754199),
(45780, 'Job 38:10', 'Job', 38, 10, 'او د دې دپاره مې حدونه جوړ کړل، او را ايسار مې کړو چې د حد نه وانۀ وړى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_10.mp3', '', 1761754199, 1761754199),
(45781, 'Job 38:11', 'Job', 38, 11, 'او ورته مې ووئيل چې د دې نه وړاندې به نۀ راځې، او ستا زورَورې چپې دې دلته ايسارې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_11.mp3', '', 1761754199, 1761754199),
(45782, 'Job 38:12', 'Job', 38, 12, 'تا کله حُکم کړے دے چې سحر دې شى، او نمر ته دې وئيلى دى چې د نمرخاتۀ طرف نه راوخېژى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_12.mp3', '', 1761754199, 1761754199),
(45783, 'Job 38:13', 'Job', 38, 13, 'تا سحر له حُکم ورکړے دے چې په زمکه خور شى، او چې د شپې بدعملى ختمه کړى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_13.mp3', '', 1761754199, 1761754199),
(45784, 'Job 38:14', 'Job', 38, 14, 'او بيا زمکه د رڼا د وجې صفا ښکارى، او رنګ يې د رنګدارو جامو په شان شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_14.mp3', '', 1761754199, 1761754199),
(45785, 'Job 38:15', 'Job', 38, 15, 'رڼا د بدعمله خلقو کارونه بندوى، او هغوئ نور ظلم زياتے نۀ شى کولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_15.mp3', '', 1761754199, 1761754199),
(45786, 'Job 38:16', 'Job', 38, 16, 'تا هغه چينې ليدلې دى چې سمندر ترې نه جوړيږى، يا تا د دې ډوبوالے معلوم کړے دے؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_16.mp3', '', 1761754199, 1761754199),
(45787, 'Job 38:17', 'Job', 38, 17, 'د مرګ دروازه تا ته ښکاره شوې ده څۀ؟ يا تا د تکې تورې تيارې دروازې ليدلې دى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_17.mp3', '', 1761754199, 1761754199),
(45788, 'Job 38:18', 'Job', 38, 18, 'تۀ د دُنيا په لوئ والى پوهه شوے يې څۀ؟ کۀ د دې نه خبر يې نو ما ته ووايه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_18.mp3', '', 1761754199, 1761754199),
(45789, 'Job 38:19', 'Job', 38, 19, 'رڼا د کوم ځائ نه راځى، او د تيارې ځائ چرته دے،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_19.mp3', '', 1761754199, 1761754199),
(45790, 'Job 38:20', 'Job', 38, 20, 'تۀ دا هر يو خپل خپل کور ته بوتلے شې څۀ؟ تا ته پته شته چې هغې ته کومه لار تلې ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_20.mp3', '', 1761754199, 1761754199),
(45791, 'Job 38:21', 'Job', 38, 21, 'خو تۀ خو به د دې هر څۀ نه خبر يې کنه؟ ځکه چې د دې پېدا کېدو نه وړاندې تۀ موجود وې، او تۀ د ډېرې مودې يې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_21.mp3', '', 1761754199, 1761754199),
(45792, 'Job 38:22', 'Job', 38, 22, 'تۀ د واورې ګودامونو ته ننوتلے يې څۀ، يا تا د ږلۍ ګودامونه ليدلى دى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_22.mp3', '', 1761754199, 1761754199),
(45793, 'Job 38:23', 'Job', 38, 23, 'هغه چې ما د مصيبت د وخت دپاره ساتلى دى، او د جنګ جګړې دپاره مې ساتلى دى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_23.mp3', '', 1761754199, 1761754199),
(45794, 'Job 38:24', 'Job', 38, 24, 'هغه ځائ ته تلے يې څۀ چرته چې نمر راخېژى، او د کوم ځائ نه چې د نمرخاتۀ هوا لګى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_24.mp3', '', 1761754199, 1761754199),
(45795, 'Job 38:25', 'Job', 38, 25, 'د دروند باران لارې چا جوړې کړې دى، او د تندر د برېښنا دپاره يې لار صفا کړې ده،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_25.mp3', '', 1761754199, 1761754199),
(45796, 'Job 38:26', 'Job', 38, 26, 'په هغه مُلک باندې څوک باران راولى چرته چې هيڅ څوک نۀ اوسيږى، په هغه صحرا باندې، چې هغه د بنيادمو نه خالى وى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_26.mp3', '', 1761754199, 1761754199),
(45797, 'Job 38:27', 'Job', 38, 27, 'چې هغه تږې او اوچه زمکه اوبۀ کړى، او چې په هغه زمکه باندې واښۀ راشنۀ کړى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_27.mp3', '', 1761754199, 1761754199),
(45798, 'Job 38:28', 'Job', 38, 28, 'ولې د باران پلار شته څۀ، يا پرخه چا پېدا کړې ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_28.mp3', '', 1761754199, 1761754199),
(45799, 'Job 38:29', 'Job', 38, 29, 'د واورې مور څوک ده؟ او د آسمان يخ له ژوند څوک ورکوى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_29.mp3', '', 1761754199, 1761754199),
(45800, 'Job 38:30', 'Job', 38, 30, 'کومه چې اوبۀ د کاڼى په شان سختې کړى، او د سمندر مخ کلک کړى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_30.mp3', '', 1761754199, 1761754199),
(45801, 'Job 38:31', 'Job', 38, 31, 'تۀ عقدِ ثُريا ستورو ته لار ښودلے شې، يا جبار ستورے په مينځ بېلولے شې څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_31.mp3', '', 1761754199, 1761754199),
(45802, 'Job 38:32', 'Job', 38, 32, 'ولې تۀ منطقتُ البُروج ستورو ته خپل موسمونه ښودلے شې، يا تۀ بناتُ النعش ستورى ته سره د هغې د بچو لار ښودلے شې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_32.mp3', '', 1761754199, 1761754199),
(45803, 'Job 38:33', 'Job', 38, 33, 'تۀ د آسمان په قانون پوهېږې څۀ؟ يا تۀ د هغوئ قانون په زمکه باندې قائمولے شې څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_33.mp3', '', 1761754199, 1761754199),
(45804, 'Job 38:34', 'Job', 38, 34, 'ولې تۀ خپل آواز وريځو ته رسولے شې څۀ، د دې دپاره چې باران ووروى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_34.mp3', '', 1761754199, 1761754199),
(45805, 'Job 38:35', 'Job', 38, 35, 'تۀ برېښنا ځلولے شې څۀ؟ يا دا پخپله مرضۍ باندې راغورزولے شې څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_35.mp3', '', 1761754199, 1761754199),
(45806, 'Job 38:36', 'Job', 38, 36, 'خبره په زړۀ کښې چا اچولې ده، او دماغو له پوهه چا ورکړې ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_36.mp3', '', 1761754199, 1761754199),
(45807, 'Job 38:37', 'Job', 38, 37, 'داسې هوښيار شته چې وريځې وشمېرى؟ يا د آسمان نه باران ورولے شى داسې لکه چې د منګى نه اوبۀ توئ کړے شى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_37.mp3', '', 1761754199, 1761754199),
(45808, 'Job 38:38', 'Job', 38, 38, 'په هغه اوچه زمکه باندې چې د خاورې نه يې لوټې جوړې شوې وى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_38.mp3', '', 1761754199, 1761754199),
(45809, 'Job 38:39', 'Job', 38, 39, 'ولې تۀ د ازمرى دپاره ښکار کولے شې، او د وړو زمرو لوږه پوره کولے شې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_39.mp3', '', 1761754199, 1761754199),
(45810, 'Job 38:40', 'Job', 38, 40, 'کله چې هغه په خپلو غارونو کښې پټ وى، يا په بوټو کښې د ښکار په اِنتظار ناست وى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_40.mp3', '', 1761754199, 1761754199);